\label{prop:Ig}
Let $g:(0,\infty)^m\to[0,\infty)$ be a measurable symmetric function
satisfying {\rm(A1)}--{\rm(A2)}. Then the NSII $I(g)$ admits the
representation
\begin{equation}
\label{eq:Ig-Dir}
I(g)
=
\frac{1}
{mC_g\sum_{r=1}^{\ell}\pi_r\alpha_r}
\sum_{j_1,\ldots,j_m=1}^{\ell}
\left(
\prod_{i=1}^{m}\pi_{j_i}
\right)
\left(
\sum_{i=1}^{m}\alpha_{j_i}
\right)
\mathbb{E}_{\operatorname{Dir}
(\alpha_{j_1},\ldots,\alpha_{j_m})}
\left[
g(V_1,\ldots,V_m)
\right],
\end{equation}
where
$
(V_1,\ldots,V_m)^\top
\sim
\operatorname{Dir}
(\alpha_{j_1},\ldots,\alpha_{j_m}).
$

\label{thm:Expectation}
Let $g:(0,\infty)^m\to[0,\infty)$ be a measurable symmetric function
satisfying {\rm(A1)}--{\rm(A2)}.  Then the expectation of the estimator \(\widehat{I(g)}\) can be written as
\[
\begin{aligned}
\mathbb{E}[\widehat{I(g)}]
=
\frac{n}{mC_g}
\sum_{j_1,\ldots,j_n=1}^{\ell}
\left(
\prod_{i=1}^{n}\pi_{j_i}
\right) 
\left(
{\sum_{i=1}^m \alpha_{j_i}} 
\right)
{
\mathbb{E}_{\operatorname{Dir}
(\alpha_{j_1},\ldots,\alpha_{j_m})}
\!\left[
g(V_1,\ldots,V_m)
\right]
\over 
\sum_{i=1}^n \alpha_{j_i}
},
\end{aligned}
\]
where
$
(V_1,\ldots,V_m)^\top
\sim
\operatorname{Dir}
(
\alpha_{j_1},
\ldots,
\alpha_{j_m}
)
$.

\label{cor:Bias}
Under the assumptions of Theorem~\ref{thm:Expectation}, we have
    \begin{multline*}
\operatorname{Bias}(\widehat{I(g)},I(g))
=
\frac{1}{mC_g}
\sum_{j_1,\ldots,j_m=1}^{\ell}
\left(
\prod_{i=1}^{m}\pi_{j_i}
\right) 
\left(
\sum_{i=1}^{m}\alpha_{j_i}
\right)
\mathbb{E}_{\operatorname{Dir}
(\alpha_{j_1},\ldots,\alpha_{j_m})}
\!\left[
g(V_1,\ldots,V_m)
\right]
\\[0,2cm]
\times 
\sum_{j_{m+1},\ldots,j_n=1}^{\ell}
\left(
\prod_{i=m+1}^{n}\pi_{j_i}
\right) 
\Bigg(
{n\over \sum_{i=1}^n \alpha_{j_i}} 
-
\frac1{\sum_{r=1}^{\ell}\pi_r\alpha_r}
\Bigg),
    \end{multline*}
where     
$
(V_1,\ldots,V_m)^\top 
\sim
\operatorname{Dir}
(
\alpha_{j_1},
\ldots,
\alpha_{j_m}
)
$.

For $\ell=1$, we have $j_1=\cdots=j_n=1$, $\pi_1=1$ and $\alpha_1=\alpha$. Hence, 
\[
\begin{aligned}
{n\over \sum_{i=1}^n \alpha_{j_i}} 
-
\frac1{\sum_{r=1}^{\ell}\pi_r\alpha_r}
=
\frac{n}{n\alpha_1}
-
\frac{1}{\alpha_1}
=
0.
\end{aligned}
\]
From Corollary \ref{cor:Bias} it follows that $\operatorname{Bias}(\widehat{I(g)},I(g))=0$.

This completes the proof.

\label{thm:strong-consistency}
Under the assumptions of Theorem~\ref{thm:Expectation},
$
\widehat{I(g)}
\xrightarrow{\mathrm{a.s.}}
I(g),
\ n\to\infty,
$
where $\xrightarrow{\mathrm{a.s.}}$ denotes almost sure convergence.
Thus, $\widehat{I(g)}$ is a strongly consistent estimator of $I(g)$

By (A2),
$
0\leqslant g(x_1,\ldots,x_m)
\leqslant C_g\sum_{i=1}^m x_i,
$
and hence $g(X_1,\ldots,X_m)$ is integrable under the finite Gamma mixture
model. Therefore, the strong law of large numbers for $U$-statistics \citep{Lee1990,Henze2024} gives
\begin{align*}
U_n(g)
\xrightarrow{\mathrm{a.s.}}
\mathbb{E}[g(X_1,\ldots,X_m)],
\end{align*}
where $U_n(g)$ is the  $U$-statistic defined in \eqref{eq:Us}.
Moreover, since $X_1$ has finite mean,
$
\overline X
\xrightarrow{\mathrm{a.s.}}
\mathbb{E}[X_1]=\mu>0.
$
Consequently,
\[
\widehat{I(g)}
\stackrel{\eqref{eq:Tn}}{=}
\frac{U_n(g)}{mC_g\overline X}
\xrightarrow{\mathrm{a.s.}}
\frac{\mathbb{E}[g(X_1,\ldots,X_m)]}
{mC_g\mu}
=
I(g).
\]

Let
$
\mu_\alpha=\sum_{r=1}^{\ell}\pi_r\alpha_r
\ \text{and}\ 
\alpha_{\min}=\min_{1\leqslant r\leqslant\ell}\alpha_r>0.
$
Since $\mathbb{P}(Y_i=j)=\pi_j$, the random variables
$\alpha_{Y_1},\alpha_{Y_2},\ldots$ are iid, with
$
\mathbb{E}[\alpha_{Y_i}]=\mu_\alpha.
$
By the strong law of large numbers and the continuous mapping
theorem,
\[
\frac{n}{\sum_{i=1}^{n}\alpha_{Y_i}}
\xrightarrow{\mathrm{a.s.}}
\frac{1}{\mu_\alpha}, \quad n\to\infty.
\]

Fix any $(j_1,\ldots,j_m)^\top\in\{1,\ldots,\ell\}^m$.
Since the remaining random variables are independent of
$Y_1,\ldots,Y_m$, the strong law of large numbers yields
\[
\frac{n}{
\sum_{i=1}^{m}\alpha_{j_i}
+\sum_{i=m+1}^{n}\alpha_{Y_i}}
\xrightarrow{\mathrm{a.s.}}
\frac{1}{\mu_\alpha}.
\]
Moreover, for every $n\geqslant m$,
\[
0<
\frac{n}{
\sum_{i=1}^{m}\alpha_{j_i}
+\sum_{i=m+1}^{n}\alpha_{Y_i}}
\leqslant \frac{1}{\alpha_{\min}}.
\]
Hence, by the dominated convergence theorem,
\[
\begin{aligned}
&\mathbb{E}\left[
\frac{n}{
\sum_{i=1}^{m}\alpha_{j_i}
+\sum_{i=m+1}^{n}\alpha_{Y_i}}
-\frac{1}{\mu_\alpha}
\right]
\longrightarrow 0, \quad n\to\infty.
\end{aligned}
\]
Equivalently, for every fixed $(j_1,\ldots,j_m)^\top$,
\[
\begin{aligned}
&\sum_{j_{m+1},\ldots,j_n=1}^{\ell}
\left(\prod_{i=m+1}^{n}\pi_{j_i}\right)
\left(
\frac{n}{\sum_{i=1}^{n}\alpha_{j_i}}
-\frac{1}{\mu_\alpha}
\right)
\longrightarrow 0, \quad n\to\infty.
\end{aligned}
\]

By Corollary~\ref{cor:Bias}, the bias is a finite sum over
$j_1,\ldots,j_m$, whose remaining factors do not depend on $n$
and are finite under the stated assumptions. Since each
corresponding inner weighted sum converges to zero, we conclude
that
$
\lim_{n\to\infty}
\operatorname{Bias}(\widehat{I(g)},I(g))=0.
$
This completes the proof.

\label{prop:second-moment}
Under the assumptions of Theorem~\ref{thm:Expectation},
\[
\begin{aligned}
\mathbb E[\widehat{I(g)}^2]
=
\frac{n^2}
{m^2C_g^2\binom{n}{m}}
\sum_{q=q_0}^{m}
\binom{m}{q}
\binom{n-m}{m-q}
H_q,
\end{aligned}
\]
where $H_q$ is as defined in \eqref{eq:Hq}.

For any generator $g$, the expectation in \eqref{eq:Hq-mixture}
admits the general representation
\begin{multline*}
\mathbb{E}_{\operatorname{Dir}(\alpha_{j_1},\ldots,\alpha_{j_{d_q}})}
\Big[
g(V_1,\ldots,V_m)
g(V_1,\ldots,V_q,V_{m+1},\ldots,V_{d_q})
\Big]
\\[0,2cm]
=
\frac{
\Gamma\!\left(\sum_{i=1}^{d_q}\alpha_{j_i}\right)
}{
\prod_{i=1}^{d_q}\Gamma(\alpha_{j_i})
}
\int_{\Delta_{d_q-1}}
g(v_1,\ldots,v_m)
g(v_1,\ldots,v_q,v_{m+1},\ldots,v_{d_q})
\prod_{i=1}^{d_q}v_i^{\alpha_{j_i}-1}
\,{\rm d}\boldsymbol v,
\end{multline*}
where
\[
\Delta_{d_q-1}
=
\left\{
(v_1,\ldots,v_{d_q})\in(0,1)^{d_q}:
\sum_{i=1}^{d_q}v_i=1
\right\},
\quad d_q=2m-q.
\]
For particular choices of $g$, the above integral may simplify further.
In general, however, the overlap between the two sets of arguments
prevents a simple closed-form expression.
The above integral therefore provides a
general expression that can be evaluated analytically or numerically for the
generators considered.

\label{thm:variance}
Under the assumptions of Theorem~\ref{thm:Expectation},
{
\begin{align*}

\operatorname{Var}[\widehat{I(g)}]
=
\frac{n^2}{m^2C_g^2}
\left\{
\frac{1}{\binom{n}{m}}
\sum_{q=q_0}^{m}
\binom{m}{q}
\binom{n-m}{m-q}
H_q
-
\left\{
\sum_{j_1,\ldots,j_n=1}^{\ell}
\left(
\prod_{i=1}^{n}\pi_{j_i}
\right) 
\left(
{\sum_{i=1}^m \alpha_{j_i}} 
\right)
{
\mathbb{E}_{\operatorname{Dir}
(\alpha_{j_1},\ldots,\alpha_{j_m})}
\!\left[
g(V_1,\ldots,V_m)
\right]
\over 
\sum_{i=1}^n \alpha_{j_i}
}
\right\}^2
\right\},
\end{align*}
}
where
$
(V_1,\ldots,V_m)^\top 
\sim
\operatorname{Dir}
(
\alpha_{j_1},
\ldots,
\alpha_{j_m}
)
$,
$
q_0=\max\{0,2m-n\},
\
d_q=2m-q,
$
and $H_q$ is as given in \eqref{eq:Hq-mixture}.

\label{cor:MSE}
Under the assumptions of Theorem~\ref{thm:variance},
{
\begin{multline*}
\!\!\!\!\!\!
\operatorname{MSE}[\widehat{I(g)}]
=
\frac{1}{m^2C_g^2}
\left\{
\frac{n^2}{\binom{n}{m}} \!
\sum_{q=q_0}^{m}
\binom{m}{q}
\binom{n-m}{m-q}
H_q
-
\left\{
n \!
\sum_{j_1,\ldots,j_n=1}^{\ell} \!
\left(
\prod_{i=1}^{n}\pi_{j_i}
\right) 
\left(
{\sum_{i=1}^m \alpha_{j_i}} 
\right)
{
\mathbb{E}_{\operatorname{Dir}
(\alpha_{j_1},\ldots,\alpha_{j_m})}
\!\left[
g(V_1,\ldots,V_m)
\right]
\over 
\sum_{i=1}^n \alpha_{j_i}
}
\right\}^2
\right.
\\[0,2cm]
+
\left.
\left\{
\sum_{j_1,\ldots,j_m=1}^{\ell} \!
\left(
\prod_{i=1}^{m}\pi_{j_i}
\right)  \!
\left(
\sum_{i=1}^{m}\alpha_{j_i}
\right)
\mathbb{E}_{\operatorname{Dir}
(\alpha_{j_1},\ldots,\alpha_{j_m})}
\!\left[
g(V_1,\ldots,V_m)
\right] \!\!
\sum_{j_{m+1},\ldots,j_n=1}^{\ell} \!
\left(
\prod_{i=m+1}^{n}\pi_{j_i}
\right)  \!
\Bigg(
{n\over \sum_{i=1}^n \alpha_{j_i}} 
-
\frac1{\sum_{r=1}^{\ell}\pi_r\alpha_r}
\Bigg)
\right\}^2
\right\}, 
\end{multline*}
} \noindent
where
$
(V_1,\ldots,V_m)^\top 
\sim
\operatorname{Dir}
(
\alpha_{j_1},
\ldots,
\alpha_{j_m}
)
$,
$
q_0=\max\{0,2m-n\},
\
d_q=2m-q,
$
and $H_q$ is as given in \eqref{eq:Hq-mixture}.

Since $\ell=1$, we have $j_1=\cdots=j_n=1$, $\pi_1=1$, and
$\alpha_1=\alpha$. The result then follows directly from
Theorem~\ref{thm:variance} and the identity
$
\sum_{q=q_0}^{m}
\binom{m}{q}
\binom{n-m}{m-q}
=
\binom{n}{m}.
$

When $m=n$, the only possible value of $q$ is
$q=q_0=n=d_q$. Therefore, by Corollary \ref{cor:variance-gamma},
\begin{align*}
\operatorname{Var}[\widehat{I(g)}]
&=
\frac{1}{C_g^2}
\left\{
\mathbb E_{\operatorname{Dir}_{n}(\alpha,\ldots,\alpha)}
\left[g(V_1,\ldots,V_n)^2\right]
-
\left[
\mathbb E_{\operatorname{Dir}_{n}(\alpha,\ldots,\alpha)}
\left[g(V_1,\ldots,V_n)\right]
\right]^2
\right\}
\\[0,2cm]
&=
\operatorname{Var}_{\operatorname{Dir}_{n}(\alpha,\ldots,\alpha)}\left[{g(V_1,\ldots,V_n)\over C_g}\right].
\end{align*}
Thus, when $m=n$, the variance reduces to the variance of
$g(V_1,\ldots,V_n)/C_g$ under the
$\operatorname{Dir}_{n}(\alpha,\ldots,\alpha)$ distribution.
